Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          CurrentSale <> null and CurrentStore <> null and CurrentSale.IsComplete = false and CurrentSale.IsReadytoPay = true and amount >= CurrentSale.Amount

            postcondition:
          result = true and CurrentSale.Belongedstore = CurrentStore and CurrentSale.Time = Now and CurrentSale.IsComplete = true and Payment.allInstances()->exists(p:Payment|p.oclIsNew() and p.AmountTendered = amount and p.BelongedSale = CurrentSale and CurrentSale.AssoicatedPayment = p and Payment.allInstances()->includes(p))

        }
